use vstd::prelude::*;

verus! {

pub spec const MAX: int = i32::MAX as int;
pub spec const MIN: int = i32::MIN as int;
# [verifier :: loop_isolation (false)] fn index_wise_addition (a : & Vec < Vec < i32 > > , b : & Vec < Vec < i32 > >) -> (c : Vec < Vec < i32 > >) requires a . len () == b . len () , forall | i : int | # ! [auto] 0 <= i < a . len () ==> a [i] . len () == b [i] . len () , forall | i : int | # ! [trigger a [i] , b [i]] 0 <= i < a . len () ==> forall | j : int | 0 <= j < a [i] . len () ==> a [i] [j] + b [i] [j] <= MAX , forall | i : int | # ! [trigger a [i] , b [i]] 0 <= i < a . len () ==> forall | j : int | 0 <= j < a [i] . len () ==> a [i] [j] + b [i] [j] >= MIN , ensures c . len () == a . len () , forall | i : int | # ! [auto] 0 <= i < c . len () ==> c [i] . len () == a [i] . len () , forall | i : int | # ! [trigger a [i] , b [i] , c [i]] 0 <= i < c . len () ==> forall | j : int | # ! [auto] 0 <= j < c [i] . len () ==> c [i] [j] == a [i] [j] + b [i] [j] , { let mut c : Vec < Vec < i32 > > = Vec :: new () ; for i in 0 .. a . len () invariant c . len () == i , forall | k : int | # ! [auto] 0 <= k < i ==> c [k] . len () == a [k] . len () , forall | k : int | # ! [trigger a [k] , b [k] , c [k]] 0 <= k < i ==> forall | j : int | # ! [auto] 0 <= j < c [k] . len () ==> c [k] [j] == a [k] [j] + b [k] [j] , { let mut row : Vec < i32 > = Vec :: new () ; for j in 0 .. a [i] . len () invariant row . len () == j , forall | l : int | # ! [auto] 0 <= l < j ==> row [l] == a [i as int] [l] + b [i as int] [l] , { row . push (a [i] [j] + b [i] [j]) ; } c . push (row) ; } c }

} // verus!